/*
 * A282241  Numbers that are the sum of 3 distinct nonzero squares in two ways
 *          with symmetrical differences: a(n) = (p-a)^2+p^2+(p+b)^2 =
 *          (q-b)^2+q^2+(q+a)^2, p, q, a, b, positive integer, a<b, p<q.
 * https://oeis.org/A282241
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   generated by merging the sequences V(p) = 3p^2 + 6kp + 2a^2 +
 *            6ak + 9k^2 for a ≥ 1, k ≥ 1, where p ≥ a + k + 1. Each distinct
 *            (a,k) defines one quadratic line; the global sequence consists
 *            of all values V(p) appearing in non‑decreasing order, with
 *            duplicates removed
 * Range:     u8 none, u16 none, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/*------------------------------------------------------------------*/
/*  Data structures                                                  */
/*------------------------------------------------------------------*/
typedef struct {
    seq_t value;     /* current value V(p)   */
    uint64_t a;      /* parameter a          */
    uint64_t k;      /* parameter k = (b-a)/3 */
    uint64_t p;      /* current p            */
} Node;

/*------------------------------------------------------------------*/
/*  Min‑heap for Node                                                */
/*------------------------------------------------------------------*/
static Node *heap = NULL;
static size_t heap_size = 0;
static size_t heap_cap  = 0;

/* push node onto heap */
static inline void push_heap(Node n)
{
    if (heap_size == heap_cap) {
        size_t new_cap = heap_cap ? heap_cap << 1 : 8;
        Node *tmp = (Node *)realloc(heap, new_cap * sizeof(Node));
        if (!tmp) exit(EXIT_FAILURE);
        heap = tmp;
        heap_cap = new_cap;
    }
    size_t i = heap_size++;
    heap[i] = n;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent].value <= heap[i].value) break;
        Node t = heap[parent];
        heap[parent] = heap[i];
        heap[i] = t;
        i = parent;
    }
}

/* pop smallest node from heap */
static inline Node pop_heap(void)
{
    Node ret = heap[0];
    heap[0] = heap[--heap_size];
    size_t i = 0;
    while (1) {
        size_t left = (i << 1) + 1;
        if (left >= heap_size) break;
        size_t right = left + 1;
        size_t child = left;
        if (right < heap_size && heap[right].value < heap[left].value)
            child = right;
        if (heap[i].value <= heap[child].value) break;
        Node t = heap[i];
        heap[i] = heap[child];
        heap[child] = t;
        i = child;
    }
    return ret;
}

/*------------------------------------------------------------------*/
/*  Storage for the generated sequence                              */
/*------------------------------------------------------------------*/
static seq_t *values = NULL;
static size_t values_len = 0;
static size_t values_cap = 0;

/* ensure capacity for at least 'needed' elements in values[] */
static inline void ensure_values_capacity(size_t needed)
{
    if (values_cap >= needed) return;
    size_t new_cap = values_cap ? values_cap << 1 : 8;
    while (new_cap < needed) new_cap <<= 1;
    seq_t *tmp = (seq_t *)realloc(values, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    values = tmp;
    values_cap = new_cap;
}

/*------------------------------------------------------------------*/
/*  Computation of V(p)                                             */
/*------------------------------------------------------------------*/
static inline seq_t compute_value(uint64_t p, uint64_t a, uint64_t k)
{
    seq_t sp = (seq_t)p;
    seq_t sa = (seq_t)a;
    seq_t sk = (seq_t)k;
    seq_t v = (seq_t)3 * sp * sp;
    v += (seq_t)6 * sk * sp;
    v += (seq_t)2 * sa * sa;
    v += (seq_t)6 * sa * sk;
    v += (seq_t)9 * sk * sk;
    return v;
}

/*------------------------------------------------------------------*/
/*  Initialization of the heap over all (a,k) pairs                 */
/*------------------------------------------------------------------*/
#define MAX_A 200      /* sufficient for n up to ≈10000 */
#define MAX_K 200

static void initialize_heap(void)
{
    heap_size = 0;
    heap_cap  = 0;
    free(heap);
    heap = NULL;

    for (uint64_t a = 1; a <= MAX_A; ++a) {
        for (uint64_t k = 1; k <= MAX_K; ++k) {
            uint64_t p0 = a + k + 1;           /* minimal admissible p */
            seq_t v0 = compute_value(p0, a, k);
            push_heap((Node){v0, a, k, p0});
        }
    }
}

/*------------------------------------------------------------------*/
/*  Sequence function                                               */
/*------------------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* safety for offset 1 */

    static bool initialized = false;
    if (!initialized) {
        initialize_heap();
        initialized = true;
        ensure_values_capacity((size_t)n);
    }

    while (values_len < (size_t)n) {
        Node nd = pop_heap();               /* smallest current value */
        if (values_len == 0 || nd.value != values[values_len - 1]) {
            ensure_values_capacity(values_len + 1);
            values[values_len++] = nd.value;
        }
        /* Advance p for this line and push the new node back. */
        nd.p++;
        nd.value = compute_value(nd.p, nd.a, nd.k);
        push_heap(nd);
    }

    return values[n - 1];
}
